    now = django.utils.timezone.now()
    for b in Booking.objects.exclude(payment_reference="").iterator():
        status = "success" if str(b.payment_status or "").lower() in ("cleared", "refund due") and b.paid_at else "initialized"
        fee = Decimal(b.fee_amount or 0)
        PaymentAttempt.objects.get_or_create(
            reference=b.payment_reference,
            defaults=dict(
                booking_ref=b.ref_code,
                amount_kobo=int(fee * 100),
                status=status,
                paid_at=b.paid_at,
                created_at=b.created_at or now,
            ),
        )
        if str(b.payment_status or "") == "Refund Due" and not Refund.objects.filter(reference=b.payment_reference).exists():
            Refund.objects.create(
                reference=b.payment_reference,
                ref_code=b.ref_code,
                patient_name=b.patient_name or "",
                amount=Decimal(b.amount_paid or b.fee_amount or 0),
                reason="clinic_full",
                status="due",
                note="Carried over: paid after the clinic filled.",
                created_by="system",
                created_at=b.paid_at or now,
            )


